var n, s;
var fill_colors = ["#ed225d", "#3caf65", "#0d40bf", "#f5b800"];
var stroke_colors = ["#0a0a0a"];
var backgroud_color = "#fafafa";
var margin = 50;

function setup() {
  createCanvas(500, 500);
  // noLoop() removed for animation
  n = floor(random(6, 10));
  s = (width-2*margin)/n;
  strokeWeight(Math.max(0.1, Math.abs(s/random([8, 10]))));
}

function draw() {
  if (random() < 1/2) {
    [stroke_colors, backgroud_color] = [[backgroud_color], stroke_colors[0]];
  }

  background(backgroud_color);

	if (random() < 1/3) {
		fill_colors = [random(fill_colors)];
	}

  if (random() < 1/2) {
    make_dots();
    make_lines();
  } else {
    [fill_colors, stroke_colors] = [stroke_colors, fill_colors];
    make_lines();
    make_dots();
  }
}

function make_dots() {
  noStroke();
  for (let i = 0; i <= n; i++) {
		let x = margin + i*s;
    for (let j = 0; j <= n; j++) {
      let y = margin + j*s;
			fill(random(fill_colors));
			circle(x, y, s/3);
    }
  }
}

function make_lines() {
	noFill();
  for (let i = 0; i < n; i++) {
		var x = margin + i*s;
    for (let j = 0; j < n; j++) {
      var y = margin + j*s;
			stroke(random(stroke_colors));
			let r = random(2);
			push();
			translate(x+s/2, y+s/2);
			rotate(random([0, PI/2, PI, 3*PI/2]));
			if (r < 1)
				arc(-s/2, -s/2, 2*s, 2*s, 0, PI/2);
			else if (r < 2)
				arc(0, -s/2, s, s, 0, PI);
			pop();
    }
  }
}
